import {
  AntiPatternSchema,
  ComponentPatternSchema,
  DesignProfileSchema,
  DesignRuleSchema,
  type AntiPattern,
  type ComponentPattern,
  type DesignProfile,
  type DesignRule,
  type KnowledgeProvenance
} from "./schemas.js";

const attribution: KnowledgeProvenance = {
  sourceId: "SRC-UDI-ORIGINAL",
  sourceName: "UDI editorial synthesis",
  organization: "Universal Design Intelligence maintainers",
  license: "MIT",
  attribution: "Original, independently authored UDI guidance; not reproduced from cited reference material.",
  references: [],
  reviewedBy: ["UDI maintainers"],
  reviewStatus: "reviewed",
  reviewedAt: "2026-10-26"
};

type RuleInput = {
  id: string;
  category: DesignRule["category"];
  title: string;
  summary: string;
  guidance: string[];
  contexts: DesignRule["contexts"];
  priority: DesignRule["priority"];
  tags: string[];
  relatedAntiPatternIds?: string[];
  choices?: DesignRule["choices"];
};

const wcagReference = {
  name: "W3C Web Content Accessibility Guidelines (WCAG) 2.2",
  url: "https://www.w3.org/TR/WCAG22/"
};

function rule(input: RuleInput): DesignRule {
  const referencesByCategory: Partial<Record<DesignRule["category"], KnowledgeProvenance["references"]>> = {
    accessibility: [wcagReference],
    "color-contrast": [wcagReference],
    forms: [
      { name: "W3C WAI: Forms Tutorial", url: "https://www.w3.org/WAI/tutorials/forms/" },
      wcagReference
    ],
    "tables-data-visualization": [
      { name: "W3C WAI: Tables Tutorial", url: "https://www.w3.org/WAI/tutorials/tables/" },
      wcagReference
    ],
    "responsive-design": [
      { name: "W3C WAI: Reflow", url: "https://www.w3.org/WAI/WCAG22/Understanding/reflow.html" }
    ]
  };
  return DesignRuleSchema.parse({
    frameworks: ["framework-agnostic"],
    relatedAntiPatternIds: [],
    choices: [],
    source: {
      ...attribution,
      references: referencesByCategory[input.category] ?? []
    },
    ...input
  });
}

export const designRules: DesignRule[] = [
  rule({ id: "UDI-VIS-001", category: "visual-hierarchy", title: "Give each screen one primary focal point", summary: "Make the principal task or message visually dominant so users can identify what matters before scanning secondary details.", guidance: ["Choose one primary heading, action, or data summary per viewport and give it the strongest combination of position, scale, and contrast.", "Reduce competing accents before adding another highlight; verify the focal point still reads at a glance."], contexts: ["all"], priority: "high", tags: ["hierarchy", "focus", "scan"] }),
  rule({ id: "UDI-VIS-002", category: "visual-hierarchy", title: "Group content by task and meaning", summary: "Use consistent proximity and section structure to make related information read as a unit without relying on decorative borders.", guidance: ["Keep labels, values, and actions close to the content they describe, and separate unrelated groups with deliberate whitespace.", "Use headings that describe the group’s purpose rather than generic labels such as “More” or “Details”."], contexts: ["all"], priority: "high", tags: ["grouping", "proximity", "content"] }),
  rule({ id: "UDI-VIS-003", category: "visual-hierarchy", title: "Make the next action visually unambiguous", summary: "A clear primary action reduces decision friction while secondary actions remain available without competing for attention.", guidance: ["Use one prominent primary action per task region and style secondary actions with lower visual emphasis.", "Keep action labels specific about outcomes, such as “Create report” instead of “Continue” when the outcome is known."], contexts: ["all"], priority: "high", tags: ["actions", "cta", "decision"] }),
  rule({ id: "UDI-VIS-004", category: "visual-hierarchy", title: "Use emphasis consistently across repeated patterns", summary: "Repeated visual roles should look alike, allowing users to recognize primary actions, headings, and status information across screens.", guidance: ["Map each semantic role to a stable visual treatment and apply it consistently across routes.", "If an element needs a unique treatment, make sure the distinction communicates a real difference in meaning or priority."], contexts: ["all"], priority: "medium", tags: ["consistency", "roles", "patterns"] }),
  rule({ id: "UDI-VIS-005", category: "visual-hierarchy", title: "Keep dense screens scannable with layered emphasis", summary: "Dashboards and complex product pages need multiple levels of emphasis that preserve a clear reading order.", guidance: ["Establish a predictable sequence from page title to section label to item detail, using measured size and weight changes.", "Use alignment and whitespace to support scanning; do not make every card or metric equally prominent."], contexts: ["dashboard", "saas", "fintech", "developer-tools"], priority: "high", tags: ["dashboard", "density", "scan"] }),
  rule({ id: "UDI-TYP-001", category: "typography", title: "Define a compact, semantic type scale", summary: "A small type scale creates consistent hierarchy and makes responsive adjustments maintainable.", guidance: ["Define named text roles for display, headings, body, labels, and supporting text rather than styling each element independently.", "Use fluid sizing only within intentional minimum and maximum bounds, and preserve readable body text on narrow screens."], contexts: ["all"], priority: "high", tags: ["type-scale", "tokens", "responsive"] }),
  rule({ id: "UDI-TYP-002", category: "typography", title: "Optimize line length for sustained reading", summary: "Long lines make it harder to track text, especially in paragraphs, documentation, and editorial content.", guidance: ["Constrain paragraph width to a comfortable measure and allow headings to use a separate, wider measure when appropriate.", "Check line wrapping at narrow and wide viewport sizes instead of relying on a single desktop screenshot."], contexts: ["all"], priority: "medium", tags: ["readability", "line-length", "content"] }),
  rule({ id: "UDI-TYP-003", category: "typography", title: "Use weight and size before decorative text effects", summary: "Clear typographic hierarchy remains legible across devices and does not depend on text shadows, outlines, or excessive letter spacing.", guidance: ["Differentiate hierarchy with a limited set of font sizes and weights, then use color as a supporting cue.", "Reserve all-caps and expanded tracking for short labels; avoid applying them to long copy or small text."], contexts: ["all"], priority: "medium", tags: ["weight", "legibility", "hierarchy"] }),
  rule({ id: "UDI-TYP-004", category: "typography", title: "Make numeric data easy to compare", summary: "Aligned digits improve quick comparison in prices, balances, tables, and time-series summaries.", guidance: ["Use tabular numerals for columns or repeated numeric values when the chosen typeface supports them.", "Align numbers by their decimal or unit position and keep units visible rather than embedding them ambiguously."], contexts: ["dashboard", "fintech", "ecommerce", "saas"], priority: "medium", tags: ["numbers", "tables", "finance"] }),
  rule({ id: "UDI-TYP-005", category: "typography", title: "Treat text truncation as an exception", summary: "Truncated labels can conceal meaning and make navigation or data difficult to identify.", guidance: ["Prefer wrapping or a wider layout for meaningful content; truncate only predictable single-line labels.", "When truncation is necessary, provide the full value through an accessible name and a usable disclosure mechanism."], contexts: ["dashboard", "saas", "developer-tools", "ecommerce"], priority: "high", tags: ["truncation", "labels", "tables"] }),
  rule({ id: "UDI-COL-001", category: "color-contrast", title: "Verify text contrast for every semantic color role", summary: "Brand colors that look distinct in a palette may fail when used for small text, disabled controls, or subtle surfaces.", guidance: ["Check foreground and background pairs against the relevant WCAG contrast criteria at actual rendered sizes.", "Test semantic states and themes separately; do not assume a color is accessible because its hue differs from the background."], contexts: ["all"], priority: "critical", tags: ["contrast", "wcag", "tokens"] }),
  rule({ id: "UDI-COL-002", category: "color-contrast", title: "Never encode status with color alone", summary: "Color-only status cues are difficult to distinguish for many users and may disappear in forced-color or monochrome modes.", guidance: ["Pair status colors with text, an icon, or another clear shape cue that carries the same meaning.", "Keep status wording explicit in tables, charts, alerts, and form validation messages."], contexts: ["all"], priority: "critical", tags: ["status", "accessibility", "semantics"] }),
  rule({ id: "UDI-COL-003", category: "color-contrast", title: "Separate semantic colors from decorative accents", summary: "Distinct token roles prevent brand accents from being mistaken for success, warning, error, or informational states.", guidance: ["Create separate tokens for brand emphasis, neutral surfaces, borders, and semantic feedback states.", "Avoid reusing the same color for unrelated actions and alerts unless their meaning remains clear through labels and context."], contexts: ["all"], priority: "high", tags: ["tokens", "semantic-color", "feedback"] }),
  rule({ id: "UDI-COL-004", category: "color-contrast", title: "Design dark themes as a separate contrast system", summary: "Simply inverting a light palette can create glare, weak hierarchy, and unreadable disabled or subtle states.", guidance: ["Define and test foreground, surface, border, and status roles for each theme rather than mechanically inverting values.", "Preserve hierarchy through measured luminance differences and verify charts and focus indicators in both themes."], contexts: ["saas", "dashboard", "developer-tools", "web-app"], priority: "high", tags: ["dark-mode", "themes", "contrast"] }),
  rule({ id: "UDI-COL-005", category: "color-contrast", title: "Preserve brand colors while fixing accessible pairings", summary: "Accessibility work can usually retain established brand hues by changing pairings, surfaces, or non-color cues.", guidance: ["When preserving a brand, first adjust foreground/background combinations, font weight, borders, and supporting labels.", "Do not replace approved brand colors without permission; document any unavoidable contrast trade-off and affected component."], contexts: ["all"], priority: "high", tags: ["brand", "contrast", "preservation"], choices: [{ dimension: "brand", value: "preserve" }] }),
  rule({ id: "UDI-LAY-001", category: "spacing-layout", title: "Use a deliberate spacing scale", summary: "A limited spacing scale creates rhythm and reduces arbitrary one-off gaps across related components.", guidance: ["Choose a compact set of spacing tokens and compose section, component, and inline gaps from those roles.", "Allow exceptions only when content or interaction needs justify them; avoid spacing values that drift screen by screen."], contexts: ["all"], priority: "high", tags: ["spacing", "tokens", "rhythm"] }),
  rule({ id: "UDI-LAY-002", category: "spacing-layout", title: "Constrain page content independently from the viewport", summary: "Wide screens need readable content bounds rather than paragraphs and forms stretched edge to edge.", guidance: ["Set a page or section maximum width and center it while keeping backgrounds free to span the viewport.", "Use narrower measures for reading and forms, and wider measures only for data-heavy or multi-column tasks."], contexts: ["all"], priority: "medium", tags: ["container", "width", "readability"] }),
  rule({ id: "UDI-LAY-003", category: "spacing-layout", title: "Align related content to shared layout rails", summary: "Shared alignment helps users connect navigation, page titles, content, and actions across a product.", guidance: ["Establish consistent horizontal content rails for headers, main sections, and footers.", "When a data table needs a wider region, make the overflow or alternate layout intentional instead of silently shifting columns."], contexts: ["all"], priority: "medium", tags: ["alignment", "grid", "consistency"] }),
  rule({ id: "UDI-LAY-004", category: "spacing-layout", title: "Use whitespace to expose structure, not hide content", summary: "Whitespace can clarify relationships but should not force frequent scrolling through low-density layouts.", guidance: ["Use larger gaps between sections than between tightly related controls, and keep repeated cards internally consistent.", "For task-oriented dashboards, prioritize compact scanability while preserving adequate target and text spacing."], contexts: ["dashboard", "saas", "fintech", "developer-tools"], priority: "medium", tags: ["whitespace", "density", "dashboard"] }),
  rule({ id: "UDI-LAY-005", category: "spacing-layout", title: "Keep interaction targets comfortably separated", summary: "Closely packed controls increase accidental activation, especially on touch screens and in dense toolbars.", guidance: ["Give adjacent interactive targets clear hit areas and enough separation to distinguish them at touch sizes.", "If space is constrained, combine related actions into a labeled menu rather than shrinking every target."], contexts: ["all"], priority: "high", tags: ["targets", "touch", "spacing"] }),
  rule({ id: "UDI-RSP-001", category: "responsive-design", title: "Reflow content without losing information", summary: "Responsive layouts must preserve essential content and actions at narrow widths rather than relying on horizontal page scrolling.", guidance: ["At narrow viewports, reflow columns, wrap content, or provide a scoped overflow region for genuinely tabular data.", "Check that headings, navigation, forms, and primary actions remain available at 320 CSS pixels and with text zoom."], contexts: ["all"], priority: "critical", tags: ["reflow", "mobile", "wcag"] }),
  rule({ id: "UDI-RSP-002", category: "responsive-design", title: "Choose breakpoints where the content needs them", summary: "Content-driven breakpoints avoid layouts that technically fit a device width but become cramped or visually unbalanced.", guidance: ["Add a breakpoint when the current layout begins to impair readability or task completion, not solely for a named device.", "Test intermediate widths and long localized text in addition to common phone, tablet, and desktop presets."], contexts: ["all"], priority: "high", tags: ["breakpoints", "testing", "content"] }),
  rule({ id: "UDI-RSP-003", category: "responsive-design", title: "Keep primary tasks reachable on small screens", summary: "Mobile layouts should not hide the product’s defining action behind excessive scrolling or desktop-only controls.", guidance: ["Identify the highest-value task for each screen and keep its entry point visible in the narrow layout.", "Move secondary controls into a discoverable menu, but preserve labels, keyboard access, and clear open/close states."], contexts: ["saas", "dashboard", "ecommerce", "fintech"], priority: "high", tags: ["mobile", "task", "navigation"] }),
  rule({ id: "UDI-RSP-004", category: "responsive-design", title: "Make dense data views adapt intentionally", summary: "Shrinking a desktop table onto a phone makes values and controls difficult to use.", guidance: ["Prioritize the columns required for the mobile task, allow horizontal scrolling when comparison requires it, or provide a stacked row presentation.", "Keep row identity and action relationships clear in alternate views and announce table headers semantically."], contexts: ["dashboard", "saas", "fintech", "ecommerce"], priority: "high", tags: ["tables", "mobile", "data"] }),
  rule({ id: "UDI-RSP-005", category: "responsive-design", title: "Respect user motion and viewport preferences", summary: "Responsive behavior includes reducing or removing motion when users request it, not just changing geometry.", guidance: ["Honor reduced-motion preferences by removing non-essential transitions and replacing animated feedback with a stable state change.", "Avoid scroll-triggered movement that obscures controls or changes content position unexpectedly."], contexts: ["all"], priority: "high", tags: ["motion", "preferences", "accessibility"], choices: [{ dimension: "motion", value: "reduced-when-requested" }] }),
  rule({ id: "UDI-NAV-001", category: "navigation", title: "Use labels that match the user’s vocabulary", summary: "Predictable navigation labels reduce guesswork and help users locate features without learning internal team terminology.", guidance: ["Name destinations by the task or content users expect there, and validate ambiguous labels with representative users when possible.", "Keep the same destination label consistent in navigation, page headings, and help text."], contexts: ["all"], priority: "high", tags: ["labels", "information-architecture", "consistency"] }),
  rule({ id: "UDI-NAV-002", category: "navigation", title: "Show users where they are in the product", summary: "A clear current-location state supports orientation in multi-route sites and complex applications.", guidance: ["Mark the active route in navigation using more than color alone and expose the current page semantically.", "For deep content structures, use breadcrumbs only when they clarify a meaningful hierarchy and each parent is actionable."], contexts: ["all"], priority: "high", tags: ["orientation", "current-page", "breadcrumbs"] }),
  rule({ id: "UDI-NAV-003", category: "navigation", title: "Keep global navigation distinct from local actions", summary: "Separating destinations from page-specific controls helps users predict the consequence of each interaction.", guidance: ["Place route changes in a consistent navigation region and task actions near the content they affect.", "Avoid mixing destructive or one-time actions into the same visual group as persistent destinations."], contexts: ["saas", "dashboard", "developer-tools", "web-app"], priority: "medium", tags: ["navigation", "actions", "structure"] }),
  rule({ id: "UDI-NAV-004", category: "navigation", title: "Scale navigation to the product’s information architecture", summary: "A useful navigation structure exposes important destinations without making every feature permanently visible.", guidance: ["Group secondary destinations under clearly named sections and keep the primary set short enough to scan.", "Use nested navigation only where parent-child relationships are meaningful and the active path remains visible."], contexts: ["saas", "dashboard", "developer-tools", "marketplace"], priority: "medium", tags: ["information-architecture", "navigation", "grouping"] }),
  rule({ id: "UDI-NAV-005", category: "navigation", title: "Make mobile navigation operable and stateful", summary: "A compact menu must communicate its state and preserve a reliable keyboard and touch interaction path.", guidance: ["Give the menu trigger an accessible name and expanded state, and make dismissal and focus return predictable.", "Avoid hiding the only route to a critical action or relying on hover to reveal destinations."], contexts: ["all"], priority: "high", tags: ["mobile", "keyboard", "menu"] }),
  rule({ id: "UDI-MKT-001", category: "marketing-landing-pages", title: "State the audience, value, and outcome above the fold", summary: "A landing page should quickly explain who the offer serves and what meaningful outcome it enables.", guidance: ["Write a specific headline around a user outcome and support it with concise proof or explanatory copy.", "Use a primary call to action that describes the next step and provide a secondary path only when it serves a distinct audience need."], contexts: ["marketing-site", "fintech", "professional-services", "developer-tools"], priority: "high", tags: ["landing-page", "value-proposition", "cta"] }),
  rule({ id: "UDI-MKT-002", category: "marketing-landing-pages", title: "Build proof next to the claim it supports", summary: "Relevant evidence is more credible when users can connect it directly to the claim being made.", guidance: ["Place customer evidence, product detail, or measurable results near the related value claim.", "Label the evidence and its scope; do not imply an endorsement, metric, or customer result without permission and substantiation."], contexts: ["marketing-site", "saas", "fintech", "professional-services"], priority: "high", tags: ["proof", "trust", "claims"] }),
  rule({ id: "UDI-MKT-003", category: "marketing-landing-pages", title: "Keep the page narrative focused on a few user questions", summary: "A sequence of clear sections helps visitors understand the offer without processing a stream of unrelated feature claims.", guidance: ["Order sections to answer what it is, why it matters, how it works, and what to do next.", "Remove repeated claims and decorative sections that do not add evidence, explanation, or a useful action."], contexts: ["marketing-site", "saas", "developer-tools", "professional-services"], priority: "medium", tags: ["narrative", "content", "focus"] }),
  rule({ id: "UDI-MKT-004", category: "marketing-landing-pages", title: "Use product imagery to explain the experience", summary: "Screenshots and illustrations should clarify a product workflow rather than act as generic decoration.", guidance: ["Show the interface or outcome relevant to the adjacent claim and use captions when context is not self-evident.", "Ensure important explanatory text is available as text and do not bake critical copy into an image."], contexts: ["marketing-site", "saas", "developer-tools", "fintech"], priority: "medium", tags: ["imagery", "product", "evidence"] }),
  rule({ id: "UDI-MKT-005", category: "marketing-landing-pages", title: "Make trust cues verifiable and proportionate", summary: "Security, compliance, customer, and performance claims should be specific enough to verify and scoped honestly.", guidance: ["Link to authoritative detail for certifications, policies, or guarantees and state the exact scope of a claim.", "Avoid invented customer logos, vague security badges, or urgency patterns that pressure visitors without a real constraint."], contexts: ["marketing-site", "fintech", "saas", "professional-services"], priority: "high", tags: ["trust", "compliance", "credibility"] }),
  rule({ id: "UDI-SAA-001", category: "saas-dashboards", title: "Lead dashboards with decisions, not decorative metrics", summary: "A dashboard earns its space by helping users understand a state or choose an action.", guidance: ["Prioritize metrics tied to a user goal and include a comparison period, unit, and definition where ambiguity is possible.", "Remove cards that have no owner, interpretation, or follow-up task."], contexts: ["dashboard", "saas", "fintech"], priority: "high", tags: ["dashboard", "metrics", "decisions"] }),
  rule({ id: "UDI-SAA-002", category: "saas-dashboards", title: "Keep dashboard filters visible and interpretable", summary: "Users need to understand which subset of data they are viewing and how a filter changes the result.", guidance: ["Show active filters near the data they affect and provide a clear way to reset or adjust them.", "Persist filter state only when it helps the workflow, and make the resulting scope visible after navigation or refresh."], contexts: ["dashboard", "saas", "fintech", "developer-tools"], priority: "high", tags: ["filters", "dashboard", "data-scope"] }),
  rule({ id: "UDI-SAA-003", category: "saas-dashboards", title: "Design for progressive disclosure of operational detail", summary: "Complex products remain approachable when the primary view summarizes state and deeper detail is available on demand.", guidance: ["Show the decision-relevant summary first and expose diagnostics, configuration, or history through a clear next step.", "Preserve the selected entity or time range when users move between summary and detail."], contexts: ["dashboard", "saas", "developer-tools", "fintech"], priority: "medium", tags: ["progressive-disclosure", "operations", "detail"] }),
  rule({ id: "UDI-SAA-004", category: "saas-dashboards", title: "Explain empty and first-use dashboard states", summary: "An empty dashboard should distinguish a new workspace from a failed load or a filtered-away result.", guidance: ["Describe why no data is shown and give a relevant next action such as connecting a source or changing a filter.", "Keep empty states specific to the current task instead of using generic celebratory artwork."], contexts: ["dashboard", "saas", "developer-tools"], priority: "high", tags: ["empty-state", "onboarding", "data"] }),
  rule({ id: "UDI-SAA-005", category: "saas-dashboards", title: "Keep workspace identity and scope clear", summary: "Multi-workspace and multi-account products must make the active organizational context obvious before users act.", guidance: ["Display the active workspace or account in a stable location and retain that scope in page headings when consequential.", "Confirm or clearly label actions that affect an entire organization rather than the current user."], contexts: ["dashboard", "saas", "fintech", "developer-tools"], priority: "critical", tags: ["workspace", "tenancy", "scope"] }),
  rule({ id: "UDI-DAT-001", category: "tables-data-visualization", title: "Use tables when precise comparison matters", summary: "Tables suit exact values, repeated attributes, and row-level actions better than decorative collections of cards.", guidance: ["Provide clear column headers and keep units, labels, and actions associated with their row or column.", "Use a chart for patterns or trends and a table when users need exact lookup or comparison."], contexts: ["dashboard", "saas", "fintech", "ecommerce"], priority: "high", tags: ["tables", "comparison", "data"] }),
  rule({ id: "UDI-DAT-002", category: "tables-data-visualization", title: "Label chart scales, units, and time ranges", summary: "A chart without visible units or scope can make accurate data appear misleading or impossible to interpret.", guidance: ["Label axes, units, relevant baselines, and the time interval in or directly beside the chart.", "Keep scale changes explicit and avoid visual encodings that exaggerate small differences."], contexts: ["dashboard", "saas", "fintech", "developer-tools"], priority: "high", tags: ["charts", "labels", "honesty"] }),
  rule({ id: "UDI-DAT-003", category: "tables-data-visualization", title: "Provide a non-visual route to chart values", summary: "Users should be able to obtain the important data and trend without relying solely on color or spatial perception.", guidance: ["Pair the visualization with a concise textual summary and accessible data labels or an equivalent table when detail matters.", "Make series names, values, and units available to assistive technology without flooding the tab order with every mark."], contexts: ["dashboard", "saas", "fintech", "developer-tools"], priority: "high", tags: ["charts", "accessibility", "data-table"] }),
  rule({ id: "UDI-DAT-004", category: "tables-data-visualization", title: "Keep row actions attached to a recognizable record", summary: "Actions in dense tables should remain associated with the correct record as the table scrolls or changes layout.", guidance: ["Include a stable row identifier and accessible action names that provide context when repeated.", "Group infrequent actions in a labeled menu and keep destructive actions distinct from routine navigation."], contexts: ["dashboard", "saas", "fintech", "ecommerce"], priority: "high", tags: ["tables", "actions", "records"] }),
  rule({ id: "UDI-DAT-005", category: "tables-data-visualization", title: "Communicate sorting and pagination state", summary: "Users need to know how rows are ordered and whether additional results are available.", guidance: ["Expose the active sort column and direction semantically and visually, and keep sorting controls keyboard-operable.", "Show the current result range and total when known; preserve the user’s position when practical after data updates."], contexts: ["dashboard", "saas", "fintech", "ecommerce"], priority: "medium", tags: ["sorting", "pagination", "tables"] }),
  rule({ id: "UDI-FOR-001", category: "forms", title: "Label every form control persistently", summary: "A visible label remains available after users start typing and is more reliable than placeholder-only instructions.", guidance: ["Associate a visible label with each field and keep examples or formats in supporting text.", "Use placeholders only for short examples, never as the only label or essential instruction."], contexts: ["all"], priority: "critical", tags: ["forms", "labels", "accessibility"], relatedAntiPatternIds: ["UDI-ANTI-001"] }),
  rule({ id: "UDI-FOR-002", category: "forms", title: "Validate at the point of need with actionable messages", summary: "Specific validation feedback helps users recover without guessing which field or format caused a problem.", guidance: ["Explain the problem in plain language beside the field, describe the expected correction, and associate the message programmatically.", "Avoid clearing valid input or showing an error before the user has a fair chance to complete the field."], contexts: ["all"], priority: "critical", tags: ["validation", "errors", "forms"], relatedAntiPatternIds: ["UDI-ANTI-002"] }),
  rule({ id: "UDI-FOR-003", category: "forms", title: "Group related fields and explain required input", summary: "Logical grouping and clear requirements reduce memory load and prevent avoidable submission errors.", guidance: ["Group related controls with a visible heading and semantic fieldset when the controls share a question.", "Mark required and optional fields consistently and explain non-obvious formats before submission."], contexts: ["all"], priority: "high", tags: ["grouping", "required-fields", "forms"] }),
  rule({ id: "UDI-FOR-004", category: "forms", title: "Preserve user input through recoverable errors", summary: "Unexpected failures should not force users to re-enter information they already supplied.", guidance: ["Keep valid values after a failed submission and identify which fields need attention.", "For sensitive values that cannot safely be retained, explain the limitation and narrow the re-entry request to those fields."], contexts: ["all"], priority: "high", tags: ["errors", "recovery", "forms"] }),
  rule({ id: "UDI-FOR-005", category: "forms", title: "Match input controls to the value and task", summary: "Appropriate control types reduce errors and improve keyboard, mobile, and assistive-technology support.", guidance: ["Use native input types and autocomplete tokens when they match the data being collected.", "Use a select only for a manageable known set; for long or searchable lists, provide an accessible search pattern."], contexts: ["all"], priority: "high", tags: ["input", "forms", "native-controls"] }),
  rule({ id: "UDI-PRC-001", category: "pricing-pages", title: "Make plan differences comparable", summary: "Prospective customers need to understand the practical difference between plans without decoding marketing jargon.", guidance: ["Use consistent feature rows, precise limits, and plain-language explanations for meaningful plan differences.", "Keep billing cadence, currency, taxes, and eligibility conditions close to the displayed price."], contexts: ["marketing-site", "saas", "fintech"], priority: "high", tags: ["pricing", "comparison", "plans"] }),
  rule({ id: "UDI-PRC-002", category: "pricing-pages", title: "Explain pricing units and billing terms", summary: "A headline price is not sufficient when billing depends on seats, usage, annual commitment, or an introductory period.", guidance: ["State the unit, billing interval, commitment, and known exclusions beside the price.", "Show the renewal or post-promotion price before a user commits to a paid plan."], contexts: ["marketing-site", "saas", "fintech", "ecommerce"], priority: "critical", tags: ["billing", "pricing", "transparency"] }),
  rule({ id: "UDI-PRC-003", category: "pricing-pages", title: "Use a recommendation badge only when criteria are clear", summary: "A highlighted plan can simplify choice, but an unsupported “popular” or “best” badge can mislead.", guidance: ["Explain the audience or capability that makes a plan a fit rather than presenting a badge without evidence.", "Keep the recommended treatment visually clear without making other plans difficult to compare or access."], contexts: ["marketing-site", "saas"], priority: "medium", tags: ["plan-selection", "honesty", "pricing"] }),
  rule({ id: "UDI-PRC-004", category: "pricing-pages", title: "Provide a clear route for non-standard buyers", summary: "Enterprise, regulated, or high-volume customers often need a buying path different from self-serve checkout.", guidance: ["Describe when to contact sales or request a quote and explain what happens after that action.", "Do not force a sales conversation for a plan that can be purchased directly unless a genuine product constraint requires it."], contexts: ["marketing-site", "saas", "fintech", "developer-tools"], priority: "medium", tags: ["enterprise", "sales", "conversion"] }),
  rule({ id: "UDI-PRC-005", category: "pricing-pages", title: "Keep plan actions specific and reversible where possible", summary: "Clear action labels and disclosed commitment terms help users choose a plan with confidence.", guidance: ["Name the next step accurately, distinguish trials from purchases, and disclose recurring billing before confirmation.", "Explain cancellation, downgrade, or trial-end terms near the relevant decision point."], contexts: ["marketing-site", "saas", "fintech"], priority: "high", tags: ["checkout", "subscription", "pricing"] }),
  rule({ id: "UDI-ACC-001", category: "accessibility", title: "Use semantic structure and meaningful headings", summary: "Semantic landmarks and a logical heading order let users navigate by page regions and content hierarchy.", guidance: ["Use native elements for headings, navigation, buttons, lists, and main content instead of styling generic containers to imitate them.", "Keep heading levels ordered by document structure, not by the font size a visual design requires."], contexts: ["all"], priority: "critical", tags: ["semantics", "headings", "landmarks"] }),
  rule({ id: "UDI-ACC-002", category: "accessibility", title: "Make keyboard focus visible and predictable", summary: "Keyboard users need to see where they are and reach all interactive functionality in a logical sequence.", guidance: ["Provide a visible focus indicator with sufficient distinction from surrounding states and avoid removing browser focus without a replacement.", "Keep tab order aligned with reading order and ensure overlays manage entry, dismissal, and focus return."], contexts: ["all"], priority: "critical", tags: ["keyboard", "focus", "wcag"] }),
  rule({ id: "UDI-ACC-003", category: "accessibility", title: "Support zoom, reflow, and text resizing", summary: "Interfaces should remain usable when users enlarge content or view the page at a narrow effective width.", guidance: ["Avoid fixed-height text containers and test content at 200% zoom and narrow viewport widths.", "Let text wrap without clipping controls, labels, or essential instructions."], contexts: ["all"], priority: "critical", tags: ["zoom", "reflow", "wcag"] }),
  rule({ id: "UDI-ACC-004", category: "accessibility", title: "Give controls names that describe their purpose", summary: "Accessible names should identify the task or destination, including when a control is icon-only or repeated.", guidance: ["Use visible text when practical and provide a concise accessible name for icon-only controls.", "Distinguish repeated row actions with record context and avoid names such as “click here” or “button”."], contexts: ["all"], priority: "critical", tags: ["accessible-name", "controls", "icons"] }),
  rule({ id: "UDI-ACC-005", category: "accessibility", title: "Respect reduced motion and non-text alternatives", summary: "Motion and imagery should not be required to understand essential content or complete a task.", guidance: ["Offer meaningful text alternatives for informative images and hide purely decorative assets from assistive technology.", "Remove non-essential movement when reduced motion is requested and avoid flashing or auto-advancing content without user control."], contexts: ["all"], priority: "high", tags: ["motion", "images", "alternatives"] }),
  rule({ id: "UDI-INT-001", category: "interaction-states", title: "Design default, hover, focus, active, and disabled states", summary: "A component is incomplete if it communicates only its resting appearance.", guidance: ["Define state treatments for pointer, keyboard, pressed, loading, and unavailable conditions as appropriate.", "Keep state changes perceivable without relying on color alone and preserve layout stability during loading."], contexts: ["all"], priority: "high", tags: ["states", "components", "interaction"] }),
  rule({ id: "UDI-INT-002", category: "interaction-states", title: "Confirm consequential and destructive actions", summary: "Users should understand the impact of irreversible or high-impact actions before they commit.", guidance: ["Use a confirmation step when the effect is difficult to reverse and name the affected entity and consequence.", "Offer undo for reversible actions when it is a safer and less disruptive recovery pattern."], contexts: ["dashboard", "saas", "fintech", "ecommerce"], priority: "high", tags: ["destructive", "confirmation", "undo"] }),
  rule({ id: "UDI-INT-003", category: "interaction-states", title: "Communicate progress for actions that take time", summary: "Visible progress and a clear completion state prevent duplicate submissions and uncertainty.", guidance: ["Show a concise pending state, prevent accidental duplicate actions, and restore a usable state if the operation fails.", "For indeterminate work, explain what is happening without inventing a percentage or blocking unrelated navigation."], contexts: ["all"], priority: "high", tags: ["loading", "progress", "feedback"] }),
  rule({ id: "UDI-INT-004", category: "interaction-states", title: "Make notifications persistent enough to act on", summary: "Transient messages should not disappear before users can perceive or use their content.", guidance: ["Keep important errors and required decisions visible until addressed; use brief status messages only for low-risk feedback.", "Do not make a timed notification the only place where a critical result or recovery action is available."], contexts: ["all"], priority: "medium", tags: ["notifications", "feedback", "errors"] }),
  rule({ id: "UDI-INT-005", category: "interaction-states", title: "Avoid hover-only affordances", summary: "Touch, keyboard, and assistive-technology users cannot depend on pointer hover to discover or operate controls.", guidance: ["Expose essential actions in the resting layout or provide an equivalent focus and touch interaction.", "If hover reveals supplementary detail, ensure the content can also be opened and dismissed through keyboard and touch."], contexts: ["all"], priority: "high", tags: ["hover", "touch", "keyboard"] }),
  rule({ id: "UDI-SYS-001", category: "design-systems", title: "Reuse the project’s established design tokens", summary: "Existing tokens preserve product identity and reduce divergence between new and established interface areas.", guidance: ["Inspect the project’s current color, typography, spacing, radius, and elevation tokens before adding styles.", "Extend the existing token model with the smallest justified addition instead of introducing a competing palette."], contexts: ["all"], priority: "critical", tags: ["design-system", "tokens", "brand"], choices: [{ dimension: "brand", value: "preserve" }] }),
  rule({ id: "UDI-SYS-002", category: "design-systems", title: "Build components around stable semantic roles", summary: "Shared components are easier to reuse when their contract reflects meaning and behavior rather than one page’s appearance.", guidance: ["Define component variants around meaningful roles such as primary action, warning, or compact density.", "Keep page-specific composition outside the shared component unless repeated use demonstrates a stable pattern."], contexts: ["all"], priority: "high", tags: ["components", "variants", "semantics"] }),
  rule({ id: "UDI-SYS-003", category: "design-systems", title: "Centralize repeated decisions without over-generalizing", summary: "A system should reduce repeated drift while keeping unique product needs explicit and understandable.", guidance: ["Promote a style or behavior into a shared token or component after it recurs with the same meaning.", "Avoid adding configuration switches for hypothetical use cases that have no current consumers."], contexts: ["all"], priority: "medium", tags: ["reuse", "maintainability", "components"] }),
  rule({ id: "UDI-SYS-004", category: "design-systems", title: "Document component states alongside appearance", summary: "Design-system guidance is incomplete when it shows only a static default state.", guidance: ["Document keyboard focus, loading, empty, error, disabled, and responsive behavior for interactive patterns.", "Add examples for long labels, localization, and high-density content where these can change the component contract."], contexts: ["all"], priority: "medium", tags: ["documentation", "states", "components"] }),
  rule({ id: "UDI-SYS-005", category: "design-systems", title: "Preserve brand decisions as an explicit constraint", summary: "A redesign should not silently replace a brand, typography system, or approved component library.", guidance: ["When brand preservation is requested, reuse approved assets and tokens and limit changes to layout, clarity, and accessible pairings.", "If a necessary improvement would change a brand decision, explain the trade-off and request approval before replacing it."], contexts: ["all"], priority: "critical", tags: ["brand", "constraints", "design-system"], choices: [{ dimension: "brand", value: "preserve" }] }),
  rule({ id: "UDI-ANT-001", category: "anti-patterns", title: "Do not use placeholders as the only field labels", summary: "Placeholder-only forms lose their field names during entry and often provide inadequate contrast or instruction.", guidance: ["Add a persistent visible label and move examples or formats to supporting text.", "Keep programmatic labels associated with the control even when a compact visual layout is required."], contexts: ["all"], priority: "critical", tags: ["forms", "labels", "anti-pattern"], relatedAntiPatternIds: ["UDI-ANTI-001"] }),
  rule({ id: "UDI-ANT-002", category: "anti-patterns", title: "Do not use vague errors that blame the user", summary: "Messages such as “invalid input” provide no useful path to recovery and can conceal the actual requirement.", guidance: ["Name the field, explain the unmet requirement, and show an acceptable example when format matters.", "Keep the value the user entered unless clearing it is necessary for safety."], contexts: ["all"], priority: "critical", tags: ["errors", "forms", "anti-pattern"], relatedAntiPatternIds: ["UDI-ANTI-002"] }),
  rule({ id: "UDI-ANT-003", category: "anti-patterns", title: "Avoid card grids that flatten every kind of content", summary: "Treating every section as an equal card creates visual noise and obscures true relationships and priorities.", guidance: ["Use cards only when grouping or separation adds meaning; otherwise use headings, lists, or shared layout rails.", "Reserve elevation and strong borders for actual containment or interaction, not as a universal decoration."], contexts: ["all"], priority: "medium", tags: ["cards", "visual-noise", "anti-pattern"] }),
  rule({ id: "UDI-ANT-004", category: "anti-patterns", title: "Avoid low-contrast placeholder and helper text", summary: "Muted supporting text can become unreadable when contrast is sacrificed to make a screen appear visually quiet.", guidance: ["Measure contrast for helper, placeholder, caption, and disabled text against their actual backgrounds.", "Reduce visual prominence with size or spacing only when minimum readability remains intact."], contexts: ["all"], priority: "critical", tags: ["contrast", "text", "anti-pattern"] }),
  rule({ id: "UDI-ANT-005", category: "anti-patterns", title: "Do not hide essential actions behind hover", summary: "Hover-only controls exclude touch users and are undiscoverable to many keyboard users.", guidance: ["Keep task-critical actions visible or reveal them through an equivalent keyboard- and touch-operable control.", "Test repeated actions in dense lists for both focus visibility and record-specific accessible names."], contexts: ["all"], priority: "high", tags: ["hover", "accessibility", "anti-pattern"] }),
  rule({ id: "UDI-ANT-006", category: "anti-patterns", title: "Avoid unbounded dashboard metric collections", summary: "A wall of equally weighted metrics makes it difficult to identify meaningful changes or decide what to do.", guidance: ["Keep metrics tied to user goals, expose definitions and comparisons, and remove redundant measures.", "Use progressive disclosure for diagnostics and secondary breakdowns."], contexts: ["dashboard", "saas", "fintech"], priority: "high", tags: ["dashboard", "metrics", "anti-pattern"] }),
  rule({ id: "UDI-ANT-007", category: "anti-patterns", title: "Do not rely on color alone for chart series or status", summary: "Color-only distinctions fail in several viewing conditions and exclude users who cannot distinguish the palette.", guidance: ["Add direct labels, shapes, patterns, or textual state and keep the mapping consistent across the chart.", "Verify the chart remains understandable in grayscale and with assistive technology."], contexts: ["dashboard", "saas", "fintech", "developer-tools"], priority: "critical", tags: ["charts", "status", "anti-pattern"] }),
  rule({ id: "UDI-ANT-008", category: "anti-patterns", title: "Avoid misleading urgency and pricing presentation", summary: "Unsubstantiated countdowns, hidden renewal terms, and ambiguous billing units undermine informed decisions.", guidance: ["Show genuine deadlines only when they are real and explain price units, cadence, and renewal conditions beside the offer.", "Do not use visual emphasis to obscure material terms or make a more expensive option appear mandatory."], contexts: ["marketing-site", "saas", "fintech", "ecommerce"], priority: "critical", tags: ["pricing", "trust", "anti-pattern"] }),
  rule({ id: "UDI-ANT-009", category: "anti-patterns", title: "Avoid shrinking desktop tables to fit mobile screens", summary: "Tiny table text and compressed actions make mobile data views inaccurate and difficult to operate.", guidance: ["Choose a mobile-specific presentation or a clearly bounded horizontal scroll region with row identity preserved.", "Keep the most important values visible and provide access to secondary columns."], contexts: ["dashboard", "saas", "fintech", "ecommerce"], priority: "high", tags: ["tables", "responsive", "anti-pattern"] }),
  rule({ id: "UDI-ANT-010", category: "anti-patterns", title: "Avoid replacing an existing visual identity without consent", summary: "Unrequested palette, typeface, and component-library changes can create costly inconsistency across a product.", guidance: ["Audit the project’s existing tokens and components before designing new ones.", "Request explicit approval before replacing the brand or established design system."], contexts: ["all"], priority: "critical", tags: ["brand", "design-system", "anti-pattern"], choices: [{ dimension: "brand", value: "preserve" }] })
];

